<?php
declare(strict_types=1);
function import_view(array $actor): void {
    require_features();$uid=(int)($_GET['user_id']??0);$person=row('SELECT * FROM ch_users WHERE id=?',[$uid]);if(!$person)throw new DomainException('Persona no encontrada.');
    $p=$_SESSION['attendance_import']??null;if($p && ((int)$p['user_id']!==$uid||(int)$p['actor_id']!==(int)$actor['id']||time()-$p['created']>1800))$p=null;
    ?><a class="back-link" href="index.php?page=user&amp;user_id=<?= $uid ?>">← Gestión de persona</a><section class="panel"><h2>Importar historial de <?= e($person['name']) ?></h2><p class="muted">RUT <?= e(rut_label($person['rut'])) ?> · Primera hoja del archivo · Hasta 2.000 filas y 5 MB.</p><p class="small muted">Columnas: RUT, Fecha, Ingreso, Salida. Coordenadas opcionales: lat_ingreso, long_ingreso, lat_salida, long_salida. No se importan fórmulas. Las filas sin horas no borran ni justifican asistencias.</p><form method="post" enctype="multipart/form-data" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="import_preview"><input type="hidden" name="user_id" value="<?= $uid ?>"><input type="hidden" name="MAX_FILE_SIZE" value="5242880"><label>Archivo .xlsx<input type="file" name="attendance_file" accept=".xlsx" required></label><label>Si una fecha ya existe<select name="mode"><option value="insert">Conservar el registro existente (agregar sólo fechas nuevas)</option><option value="update">Actualizar ingreso, salida y coordenadas importadas</option></select></label><label>Motivo de la importación<textarea name="reason" maxlength="800" required placeholder="Carga o actualización del historial de asistencia"></textarea></label><button class="button primary">Analizar y mostrar vista previa</button></form></section>
<?php if($p): ?><section class="panel"><h2>Vista previa · <?= e($p['filename']) ?></h2><p>Hoja <?= e($p['sheet']) ?> · <?= (int)$p['count'] ?> cambio(s) · <?= count($p['skipped']) ?> día(s) sin horas · <?= count($p['errors']) ?> error(es).</p><p class="small muted">Los horarios se interpretan en <?= e(settings()['timezone']) ?>. Las ubicaciones se incorporan al registro; los antecedentes se conservan para trazabilidad.</p><?php if($p['errors']): ?><div class="notice error"><strong>Corrige estos errores y vuelve a seleccionar el archivo. No se guardará ninguna fila mientras existan errores.</strong><ul><?php foreach($p['errors'] as $error)echo '<li>'.e($error).'</li>'; ?></ul></div><?php endif; ?><div class="table-wrap import-preview"><table><thead><tr><th>Fila</th><th>Fecha</th><th>Actual</th><th>Archivo</th><th>Coordenadas del archivo</th><th>Acción</th></tr></thead><tbody><?php foreach($p['rows'] as $r): ?><tr><td><?= (int)$r['line'] ?></td><td><?= e(date_label($r['date'])) ?></td><td><?= $r['before']?e(local_time($r['before']['clock_in'],'H:i:s').' – '.local_time($r['before']['clock_out'],'H:i:s')):'Sin registro' ?></td><td><?= e(local_time($r['clock_in'],'H:i:s').' – '.local_time($r['clock_out'],'H:i:s')) ?></td><td><small>Ingreso: <?= $r['in_lat']===null?'Sin datos':e($r['in_lat'].', '.$r['in_lng']) ?></small><small>Salida: <?= $r['out_lat']===null?'Sin datos':e($r['out_lat'].', '.$r['out_lng']) ?></small></td><td><?= e(['insert'=>'Crear','update'=>'Actualizar','existing'=>'Conservar existente','unchanged'=>'Sin cambios'][$r['action']]) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($p['skipped']): ?><details><summary>Ver días sin horas omitidos</summary><ul><?php foreach($p['skipped'] as $r)echo '<li>Fila '.(int)$r['line'].' · '.e(date_label($r['date']).' · '.$r['why']).'</li>'; ?></ul></details><?php endif; ?>
<?php if(!$p['errors'] && $p['count']): ?><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="import_confirm"><input type="hidden" name="preview_token" value="<?= e($p['token']) ?>"><?php if($p['extend_from']): ?><div class="notice warning"><label class="check"><input type="checkbox" name="extend_history" required> Ampliar el historial y la fecha de inicio de esta persona hasta <?= e(date_label($p['extend_from'])) ?>.</label><p>Si no hay horario para ese período, se aplicará el primer horario registrado de la persona. Verifica su vigencia en Gestión de persona: esto afecta la meta histórica. El cambio quedará auditado.</p></div><?php endif; ?><p>Se confirmarán <?= (int)$p['count'] ?> cambio(s) con motivo: <strong><?= e($p['reason']) ?></strong>.</p><button class="button primary">Confirmar importación</button></form><?php endif; ?></section><?php endif; ?>
<section class="panel"><h2>Importaciones anteriores</h2><?php $batches=rows('SELECT b.*,u.name actor FROM ch_import_batches b JOIN ch_users u ON u.id=b.actor_id WHERE b.user_id=? ORDER BY b.id DESC LIMIT 30',[$uid]);if(!$batches)echo '<p class="empty">Todavía no hay importaciones.</p>';foreach($batches as $b)echo '<article class="evidence"><strong>#'.(int)$b['id'].' · '.e($b['filename']).'</strong><p class="small muted">'.e(local_time($b['created_at'],'d/m/Y H:i').' · '.$b['actor']).'</p><p>'.e($b['reason']).'</p></article>'; ?></section><?php
}
function absences_view(array $actor,bool $review=false): void {
    require_features();$status=is_string($_GET['status']??null)?$_GET['status']:($review?'pending':'all');if(!in_array($status,['all','pending','approved','rejected','cancelled','revoked'],true))$status='pending';
    $where=$review?'1=1':'a.user_id=?';$params=$review?[]:[$actor['id']];if($status!=='all'){$where.=' AND a.status=?';$params[]=$status;}
    $total=(int)query('SELECT COUNT(*) FROM ch_absences a WHERE '.$where,$params)->fetchColumn();$pages=max(1,(int)ceil($total/40));$pg=min($pages,max(1,(int)($_GET['p']??1)));
    $list=rows('SELECT a.*,u.name,u.rut,r.name reviewer FROM ch_absences a JOIN ch_users u ON u.id=a.user_id LEFT JOIN ch_users r ON r.id=a.reviewed_by WHERE '.$where.' ORDER BY a.created_at DESC,a.id DESC LIMIT 40 OFFSET '.(($pg-1)*40),$params);
    ?><p class="page-description"><?= $review?'Revisa las justificaciones de las personas. Las aprobadas cubren el horario como horas justificadas, sin reducir la meta semanal.':'Justifica una inasistencia y consulta su resolución. La aprobación cubre tu horario como horas justificadas, sin crear marcados ni reducir la meta semanal.' ?></p><?php if(!$review): ?><section class="panel"><h2>Nueva justificación</h2><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="absence_request"><div class="form-grid"><label>Desde<input type="date" name="from" min="<?= e($actor['start_date']) ?>" max="<?= e(today()) ?>" required></label><label>Hasta (opcional)<input type="date" name="to" min="<?= e($actor['start_date']) ?>" max="<?= e(today()) ?>"></label></div><label>Motivo<select name="category"><?php foreach(absence_categories() as $key=>$label)echo '<option value="'.$key.'">'.e($label).'</option>'; ?></select></label><label>Comentario (opcional)<textarea name="note" maxlength="1000" placeholder="Agrega una aclaración si es necesaria."></textarea></label><p class="small muted">Para un día, completa sólo Desde. Los rangos crean una solicitud por fecha (hasta 90 días), incluidos descansos y feriados. Sólo se admiten días sin asistencia registrada.</p><button class="button primary">Enviar para revisión</button></form></section><?php endif; ?>
<section class="panel"><form method="get" class="inline-form"><input type="hidden" name="page" value="<?= $review?'requests':'absences' ?>"><label>Estado<select name="status"><?php foreach(['all'=>'Todos','pending'=>'Pendientes','approved'=>'Aprobadas','rejected'=>'Rechazadas','cancelled'=>'Canceladas','revoked'=>'Revocadas'] as $key=>$label)echo '<option value="'.$key.'" '.($key===$status?'selected':'').'>'.e($label).'</option>'; ?></select></label><button class="button secondary">Filtrar</button></form><?php if(!$list)echo '<p class="empty">No hay solicitudes con este filtro.</p>';foreach($list as $a): ?><article class="absence-card"><div class="panel-heading"><h3><?= e(date_label($a['work_date']).' · '.absence_categories()[$a['category']]) ?></h3><?= status_badge(absence_status($a['status'])) ?></div><?php if($review): ?><p><?= e($a['name'].' · '.rut_label($a['rut'])) ?></p><?php endif; ?><p><?= e($a['note']?:'Sin comentario adicional.') ?></p><p class="small muted">Enviada: <?= e(local_time($a['created_at'],'d/m/Y H:i')) ?><?php if($a['reviewed_at']): ?> · <?= e($a['reviewer']??'') ?> · <?= e(local_time($a['reviewed_at'],'d/m/Y H:i')) ?><?php endif; ?></p><?php if($a['review_note'])echo '<p><strong>Resolución:</strong> '.e($a['review_note']).'</p>'; ?>
<?php $canReview=$review && in_array($actor['role'],['admin','analyst'],true) && $a['status']==='pending' && (int)$a['user_id']!==(int)$actor['id'];$canRevoke=$review && $actor['role']==='admin' && $a['status']==='approved';$canCancel=!$review && $a['status']==='pending';if($canReview||$canRevoke||$canCancel): ?><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="absence_decision"><input type="hidden" name="absence_id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$a['revision'] ?>"><label>Motivo de la resolución<input name="reason" maxlength="1000" required></label><div class="actions"><?php if($canReview): ?><button class="button primary" name="decision" value="approved">Aprobar</button><button class="button secondary" name="decision" value="rejected">Rechazar</button><?php elseif($canRevoke): ?><button class="button danger" name="decision" value="revoked">Revocar aprobación</button><?php else: ?><button class="button secondary" name="decision" value="cancelled">Cancelar solicitud</button><?php endif; ?></div></form><?php elseif($review && $a['status']==='pending' && $actor['role']!=='auditor'): ?><p class="small muted">Tu solicitud debe ser revisada por otro analista o administrador.</p><?php endif; ?></article><?php endforeach; ?><div class="pagination"><span>Página <?= $pg ?> de <?= $pages ?></span><?php foreach([$pg-1=>'Anterior',$pg+1=>'Siguiente'] as $p=>$label)if($p>=1&&$p<=$pages)echo '<a href="index.php?'.e(http_build_query(['page'=>$review?'requests':'absences','status'=>$status,'p'=>$p])).'">'.$label.'</a>'; ?></div></section><?php
}
